  private static JobFinishedEvent createJobFinishedEvent(JobImpl job) {
    job.mayBeConstructFinalFullCounters();
    return new JobFinishedEvent(
        job.oldJobId, job.finishTime,
        job.succeededMapTaskCount, job.succeededReduceTaskCount,
        job.failedMapTaskCount, job.failedReduceTaskCount,
        job.finalMapCounters,
        job.finalReduceCounters,
        job.fullCounters);
  }

  private void mayBeConstructFinalFullCounters() {
    synchronized (fullCountersLock) {
      if (fullCounters != null) {
        return;
      }
      constructFinalFullcounters();
    }
  }

  @Private
  public void constructFinalFullcounters() {
    fullCounters = new Counters();
    finalMapCounters = new Counters();
    finalReduceCounters = new Counters();
    fullCounters.incrAllCounters(jobCounters);
    for (Task t : tasks.values()) {
      Counters counters = t.getCounters();
      switch (t.getType()) {
        case MAP:
          finalMapCounters.incrAllCounters(counters);
          break;
        case REDUCE:
          finalReduceCounters.incrAllCounters(counters);
          break;
        default:
          throw new IllegalStateException("Task type neither map nor reduce: " + 
              t.getType());
      }
      fullCounters.incrAllCounters(counters);
    }
  }

