  private void handleTaskAttemptCompletion(JobTaskAttemptCompletedEvent event) {
    TaskAttemptCompletionEvent tce = event.getCompletionEvent();
    tce.setEventId(taskAttemptCompletionEvents.size());
    taskAttemptCompletionEvents.add(tce);
    int mapEventIdx = -1;
    if (TaskType.MAP.equals(tce.getAttemptId().getTaskId().getTaskType())) {
      mapEventIdx = mapAttemptCompletionEvents.size();
      mapAttemptCompletionEvents.add(TypeConverter.fromYarn(tce));
    }
    taskCompletionIdxToMapCompletionIdx.add(mapEventIdx);
    TaskAttemptId attemptId = tce.getAttemptId();
    TaskId taskId = attemptId.getTaskId();
    Integer successEventNo = successAttemptCompletionEventNoMap.remove(taskId);
    if (successEventNo != null) {
      TaskAttemptCompletionEvent successEvent = 
          taskAttemptCompletionEvents.get(successEventNo);
      successEvent.setStatus(TaskAttemptCompletionEventStatus.OBSOLETE);
      int mapCompletionIdx = taskCompletionIdxToMapCompletionIdx.get(successEventNo);
      if (mapCompletionIdx >= 0) {
        TaskCompletionEvent mapEvent = mapAttemptCompletionEvents.get(mapCompletionIdx);
        mapAttemptCompletionEvents.set(mapCompletionIdx,
            new TaskCompletionEvent(mapEvent.getEventId(),
                mapEvent.getTaskAttemptId(), mapEvent.idWithinJob(),
                mapEvent.isMapTask(), TaskCompletionEvent.Status.OBSOLETE,
                mapEvent.getTaskTrackerHttp()));
      }
    }
    if (TaskAttemptCompletionEventStatus.SUCCEEDED.equals(tce.getStatus())) {
      successAttemptCompletionEventNoMap.put(taskId, tce.getEventId());
      Task task = tasks.get(taskId);
      TaskAttempt attempt = task.getAttempt(attemptId);
      NodeId nodeId = attempt.getNodeId();
      assert (nodeId != null);
      List<TaskAttemptId> list = nodesToSucceededTaskAttempts.get(nodeId);
      if (list == null) {
        list = new ArrayList<>();
        nodesToSucceededTaskAttempts.put(nodeId, list);
      }
      list.add(attempt.getID());
    }
  }

  private static class TaskAttemptFetchFailureTransition implements
      SingleArcTransition<JobImpl, JobEvent> {
    @Override
    public void transition(JobImpl job, JobEvent event) {
      job.handleFetchFailure((JobTaskAttemptFetchFailureEvent) event);
    }
  }

  private void handleFetchFailure(JobTaskAttemptFetchFailureEvent event) {
    int shufflingReduceTasks = 0;
    for (TaskId taskId : reduceTasks) {
      Task task = tasks.get(taskId);
      if (TaskState.RUNNING.equals(task.getState())) {
        for (TaskAttempt attempt : task.getAttempts().values()) {
          if (attempt.getPhase() == Phase.SHUFFLE) {
            shufflingReduceTasks++;
            break;
          }
        }
      }
    }
    for (TaskAttemptId mapId : event.getMaps()) {
      Integer fetchFailures = fetchFailuresMapping.get(mapId);
      fetchFailures = (fetchFailures == null) ? 1 : (fetchFailures + 1);
      fetchFailuresMapping.put(mapId, fetchFailures);
      float failureRate = shufflingReduceTasks == 0 ? 1.0f :
          (float) fetchFailures / shufflingReduceTasks;
      if (fetchFailures >= getMaxFetchFailuresNotifications()
          && failureRate >= getMaxAllowedFetchFailuresFraction()) {
        LOG.info("Too many fetch-failures for output of task attempt: " + 
            mapId + " ... raising fetch failure to map");
        eventHandler.handle(new TaskAttemptEvent(mapId, 
            TaskAttemptEventType.TA_TOO_MANY_FETCH_FAILURE));
        fetchFailuresMapping.remove(mapId);
      }
    }
  }

  private static class TaskCompletedTransition implements
      MultipleArcTransition<JobImpl, JobEvent, JobStateInternal> {

    @Override
    public JobStateInternal transition(JobImpl job, JobEvent event) {
      job.completedTaskCount++;
      LOG.info("Num completed Tasks: " + job.completedTaskCount);
      JobTaskEvent taskEvent = (JobTaskEvent) event;
      Task task = job.tasks.get(taskEvent.getTaskID());
      switch (taskEvent.getState()) {
        case SUCCEEDED:
          job.taskSucceeded(task);
          break;
        case FAILED:
          job.taskFailed(task);
          break;
        case KILLED:
          job.taskKilled(task);
          break;
        default:
          break;
      }
      return job.evaluateJobCompletion();
    }

    private JobStateInternal evaluateJobCompletion(JobImpl job) {
      if (job.failedMapTaskCount * 100 > 
          job.allowedMapFailuresPercent * job.numMapTasks ||
          job.failedReduceTaskCount * 100 > 
          job.allowedReduceFailuresPercent * job.numReduceTasks) {
        job.setFinishTime();
        String diagnosticMsg = "Job failed as tasks failed. " +
            "failedMaps:" + job.failedMapTaskCount + 
            " failedReduces:" + job.failedReduceTaskCount;
        LOG.info(diagnosticMsg);
        job.addDiagnostic(diagnosticMsg);
        boolean allDone = true;
        for (Task task : job.tasks.values()) {
          if (!task.isFinished()) {
            allDone = false;
            job.eventHandler.handle(
                new TaskEvent(task.getID(), TaskEventType.T_KILL));
          }
        }
        if (allDone) {
          job.eventHandler.handle(new CommitterJobAbortEvent(job.jobId,
              job.jobContext,
              org.apache.hadoop.mapreduce.JobStatus.State.FAILED));
          return JobStateInternal.FAIL_ABORT;
        }
        job.failWaitTriggerScheduledFuture = job.executor.schedule(
            new TriggerScheduledFuture(job, new JobEvent(job.getID(),
                JobEventType.JOB_FAIL_WAIT_TIMEDOUT)),
            job.conf.getInt(MRJobConfig.MR_AM_COMMITTER_CANCEL_TIMEOUT_MS,
                MRJobConfig.DEFAULT_MR_AM_COMMITTER_CANCEL_TIMEOUT_MS),
            TimeUnit.MILLISECONDS);
        return JobStateInternal.FAIL_WAIT;
      }
      return job.checkReadyForCommit();
    }
  }

  private static class TriggerScheduledFuture implements Runnable {
    private final JobEvent toSend;
    private final JobImpl job;
    TriggerScheduledFuture(JobImpl job, JobEvent toSend) {
      this.toSend = toSend;
      this.job = job;
    }
    public void run() {
      LOG.info("Sending event " + toSend + " to " + job.getID());
      job.getEventHandler().handle(toSend);
    }
  }

  private void taskSucceeded(Task task) {
    if (task.getType() == TaskType.MAP) {
      succeededMapTaskCount++;
    } else {
      succeededReduceTaskCount++;
    }
    metrics.completedTask(task);
  }

  private void taskFailed(Task task) {
    if (task.getType() == TaskType.MAP) {
      failedMapTaskCount++;
    } else if (task.getType() == TaskType.REDUCE) {
      failedReduceTaskCount++;
    }
    addDiagnostic("Task failed " + task.getID());
    metrics.failedTask(task);
  }

  private void taskKilled(Task task) {
    if (task.getType() == TaskType.MAP) {
      killedMapTaskCount++;
    } else if (task.getType() == TaskType.REDUCE) {
      killedReduceTaskCount++;
    }
    metrics.killedTask(task);
  }

