  /**
   * Decide whether job can be run in uber mode based on various criteria.
   * @param dataInputLength Total length for all splits
   */
  private void makeUberDecision(long dataInputLength) {
    int sysMaxMaps = conf.getInt(MRJobConfig.JOB_UBERTASK_MAXMAPS, 9);
    int sysMaxReduces = conf.getInt(MRJobConfig.JOB_UBERTASK_MAXREDUCES, 1);
    long sysMaxBytes = conf.getLong(MRJobConfig.JOB_UBERTASK_MAXBYTES,
        fs.getDefaultBlockSize(this.remoteJobSubmitDir));

    long sysMemSizeForUberSlot =
        conf.getInt(MRJobConfig.MR_AM_VMEM_MB,
            MRJobConfig.DEFAULT_MR_AM_VMEM_MB);
    long sysCPUSizeForUberSlot =
        conf.getInt(MRJobConfig.MR_AM_CPU_VCORES,
            MRJobConfig.DEFAULT_MR_AM_CPU_VCORES);

    boolean uberEnabled =
        conf.getBoolean(MRJobConfig.JOB_UBERTASK_ENABLE, false);
    boolean smallNumMapTasks = (numMapTasks <= sysMaxMaps);
    boolean smallNumReduceTasks = (numReduceTasks <= sysMaxReduces);
    boolean smallInput = (dataInputLength <= sysMaxBytes);
    long requiredMapMB = conf.getLong(MRJobConfig.MAP_MEMORY_MB, 0);
    long requiredReduceMB = conf.getLong(MRJobConfig.REDUCE_MEMORY_MB, 0);
    long requiredMB = Math.max(requiredMapMB, requiredReduceMB);
    int requiredMapCores = conf.getInt(
        MRJobConfig.MAP_CPU_VCORES,
        MRJobConfig.DEFAULT_MAP_CPU_VCORES);
    int requiredReduceCores = conf.getInt(
        MRJobConfig.REDUCE_CPU_VCORES,
        MRJobConfig.DEFAULT_REDUCE_CPU_VCORES);
    int requiredCores = Math.max(requiredMapCores, requiredReduceCores);
    if (numReduceTasks == 0) {
      requiredMB = requiredMapMB;
      requiredCores = requiredMapCores;
    }
    boolean smallMemory =
        (requiredMB <= sysMemSizeForUberSlot)
            || (sysMemSizeForUberSlot == JobConf.DISABLED_MEMORY_LIMIT);
    boolean smallCpu = requiredCores <= sysCPUSizeForUberSlot;
    boolean notChainJob = !isChainJob(conf);

    isUber = uberEnabled && smallNumMapTasks && smallNumReduceTasks
        && smallInput && smallMemory && smallCpu
        && notChainJob;

    if (isUber) {
      LOG.info("Uberizing job " + jobId + ": " + numMapTasks + "m+"
          + numReduceTasks + "r tasks (" + dataInputLength
          + " input bytes) will run sequentially on single node.");

      conf.setFloat(MRJobConfig.COMPLETED_MAPS_FOR_REDUCE_SLOWSTART,
          1.0f);
      conf.setInt(MRJobConfig.MAP_MAX_ATTEMPTS, 1);
      conf.setInt(MRJobConfig.REDUCE_MAX_ATTEMPTS, 1);
      conf.setBoolean(MRJobConfig.MAP_SPECULATIVE, false);
      conf.setBoolean(MRJobConfig.REDUCE_SPECULATIVE, false);
    } else {
      StringBuilder msg = new StringBuilder();
      msg.append("Not uberizing ").append(jobId).append(" because:");
      if (!uberEnabled)
        msg.append(" not enabled;");
      if (!smallNumMapTasks)
        msg.append(" too many maps;");
      if (!smallNumReduceTasks)
        msg.append(" too many reduces;");
      if (!smallInput)
        msg.append(" too much input;");
      if (!smallCpu)
        msg.append(" too much CPU;");
      if (!smallMemory)
        msg.append(" too much RAM;");
      if (!notChainJob)
        msg.append(" chainjob;");
      LOG.info(msg.toString());
    }
  }

  /**
   * ChainMapper and ChainReducer must execute in parallel, so they're not
   * compatible with uberization/LocalContainerLauncher (100% sequential).
   */
  private boolean isChainJob(Configuration conf) {
    boolean isChainJob = false;
    try {
      String mapClassName = conf.get(MRJobConfig.MAP_CLASS_ATTR);
      if (mapClassName != null) {
        Class<?> mapClass = Class.forName(mapClassName);
        if (ChainMapper.class.isAssignableFrom(mapClass))
          isChainJob = true;
      }
    } catch (ClassNotFoundException cnfe) {
    } catch (NoClassDefFoundError ignored) {
    }
    try {
      String reduceClassName = conf.get(MRJobConfig.REDUCE_CLASS_ATTR);
      if (reduceClassName != null) {
        Class<?> reduceClass = Class.forName(reduceClassName);
        if (ChainReducer.class.isAssignableFrom(reduceClass))
          isChainJob = true;
      }
    } catch (ClassNotFoundException cnfe) {
    } catch (NoClassDefFoundError ignored) {
    }
    return isChainJob;
  }

  private void actOnUnusableNode(NodeId nodeId, NodeState nodeState) {
    List<TaskAttemptId> taskAttemptIdList = nodesToSucceededTaskAttempts.get(nodeId);
    if (taskAttemptIdList != null) {
      String mesg = "TaskAttempt killed because it ran on unusable node "
          + nodeId;
      for (TaskAttemptId id : taskAttemptIdList) {
        if (TaskType.MAP == id.getTaskId().getTaskType()) {
          LOG.info(mesg + ". AttemptId:" + id);
          eventHandler.handle(new TaskAttemptKillEvent(id, mesg));
        }
      }
    }
  }

  private static String getWorkflowAdjacencies(Configuration conf) {
    int prefixLen = MRJobConfig.WORKFLOW_ADJACENCY_PREFIX_STRING.length();
    Map<String, String> adjacencies =
        conf.getValByRegex(MRJobConfig.WORKFLOW_ADJACENCY_PREFIX_PATTERN);
    if (adjacencies.isEmpty()) {
      return "";
    }
    int size = 0;
    for (Entry<String, String> entry : adjacencies.entrySet()) {
      int keyLen = entry.getKey().length();
      size += keyLen - prefixLen;
      size += entry.getValue().length() + 6;
    }
    StringBuilder sb = new StringBuilder(size);
    for (Entry<String, String> entry : adjacencies.entrySet()) {
      int keyLen = entry.getKey().length();
      sb.append("\"");
      sb.append(escapeString(entry.getKey().substring(prefixLen, keyLen)));
      sb.append("\"=\"");
      sb.append(escapeString(entry.getValue()));
      sb.append("\" ");
    }
    return sb.toString();
  }

  public static String escapeString(String data) {
    return StringUtils.escapeString(data, StringUtils.ESCAPE_CHAR,
        new char[] {'"', '=', '.'});
  }

  public static class InitTransition
      implements MultipleArcTransition<JobImpl, JobEvent, JobStateInternal> {

    @Override
    public JobStateInternal transition(JobImpl job, JobEvent event) {
      return job.initializeJob();
    }
  }

  private JobStateInternal initializeJob() {
    metrics.submittedJob(this);
    metrics.preparingJob(this);
    if (newApiCommitter) {
      jobContext = new JobContextImpl(conf, oldJobId);
    } else {
      jobContext = new org.apache.hadoop.mapred.JobContextImpl(conf, oldJobId);
    }
    try {
      setupJob();
      fs = getFileSystem(conf);
      logJobSubmission();
      TaskSplitMetaInfo[] splits = createSplits();
      numMapTasks = splits.length;
      numReduceTasks = conf.getInt(MRJobConfig.NUM_REDUCES, 0);
      adjustWeights();
      checkTaskLimits();
      long inputLength = computeInputLength(splits);
      makeUberDecision(inputLength);
      initCompletionEventLists();
      allowedMapFailuresPercent = conf.getInt(MRJobConfig.MAP_FAILURES_MAX_PERCENT, 0);
      allowedReduceFailuresPercent = conf.getInt(MRJobConfig.REDUCE_FAILURES_MAXPERCENT, 0);
      createMapTasks(splits, inputLength);
      createReduceTasks();
      metrics.endPreparingJob(this);
      return JobStateInternal.INITED;
    } catch (Exception e) {
      LOG.warn("Job init failed", e);
      metrics.endPreparingJob(this);
      addDiagnostic("Job init failed : " + StringUtils.stringifyException(e));
      return JobStateInternal.NEW;
    }
  }

  private void setupJob() throws IOException {
    String oldJobIDString = oldJobId.toString();
    String user = UserGroupInformation.getCurrentUser().getShortUserName();
    Path path = MRApps.getStagingAreaDir(conf, user);
    if (LOG.isDebugEnabled()) {
      LOG.debug("startJobs: parent=" + path + " child=" + oldJobIDString);
    }
    remoteJobSubmitDir = FileSystem.get(conf).makeQualified(
        new Path(path, oldJobIDString));
    remoteJobConfFile = new Path(remoteJobSubmitDir, MRJobConfig.JOB_CONF_FILE);
    JobTokenIdentifier identifier = new JobTokenIdentifier(new Text(oldJobIDString));
    jobToken = new Token<JobTokenIdentifier>(identifier, jobTokenSecretManager);
    jobToken.setService(identifier.getJobId());
    jobTokenSecretManager.addTokenForJob(oldJobIDString, jobToken);
    LOG.info("Adding job token for " + oldJobIDString + " to jobTokenSecretManager");
    if (TokenCache.getShuffleSecretKey(jobCredentials) == null) {
      LOG.warn("Shuffle secret key missing from job credentials."
          + " Using job token secret as shuffle secret.");
      TokenCache.setShuffleSecretKey(jobToken.getPassword(), jobCredentials);
    }
  }

  private void logJobSubmission() {
    JobSubmittedEvent jse = new JobSubmittedEvent(oldJobId,
        conf.get(MRJobConfig.JOB_NAME, "test"),
        conf.get(MRJobConfig.USER_NAME, "mapred"),
        appSubmitTime,
        remoteJobConfFile.toString(),
        jobACLs, queueName,
        conf.get(MRJobConfig.WORKFLOW_ID, ""),
        conf.get(MRJobConfig.WORKFLOW_NAME, ""),
        conf.get(MRJobConfig.WORKFLOW_NODE_NAME, ""),
        getWorkflowAdjacencies(conf),
        conf.get(MRJobConfig.WORKFLOW_TAGS, ""));
    eventHandler.handle(new JobHistoryEvent(jobId, jse));
  }

  private TaskSplitMetaInfo[] createSplits() {
    try {
      return SplitMetaInfoReader.readSplitMetaInfo(
          oldJobId, fs, conf, remoteJobSubmitDir);
    } catch (IOException e) {
      throw new YarnRuntimeException(e);
    }
  }

  private void adjustWeights() {
    if (numMapTasks == 0 && numReduceTasks == 0) {
      addDiagnostic("No of maps and reduces are 0 " + jobId);
    } else if (numMapTasks == 0) {
      reduceWeight = 0.9f;
    } else if (numReduceTasks == 0) {
      mapWeight = 0.9f;
    } else {
      mapWeight = reduceWeight = 0.45f;
    }
  }

  private long computeInputLength(TaskSplitMetaInfo[] splits) {
    long inputLength = 0;
    for (int i = 0; i < numMapTasks; ++i) {
      inputLength += splits[i].getInputDataLength();
    }
    return inputLength;
  }

  private void initCompletionEventLists() {
    taskAttemptCompletionEvents = new ArrayList<TaskAttemptCompletionEvent>(
        numMapTasks + numReduceTasks + 10);
    mapAttemptCompletionEvents = new ArrayList<TaskCompletionEvent>(numMapTasks + 10);
    taskCompletionIdxToMapCompletionIdx = new ArrayList<Integer>(
        numMapTasks + numReduceTasks + 10);
  }

  private void createMapTasks(TaskSplitMetaInfo[] splits, long inputLength) {
    for (int i = 0; i < numMapTasks; ++i) {
      TaskImpl task = new MapTaskImpl(jobId, i,
          eventHandler,
          remoteJobConfFile,
          conf, splits[i],
          taskAttemptListener,
          jobToken, jobCredentials,
          clock,
          applicationAttemptId.getAttemptId(),
          metrics, appContext);
      addTask(task);
    }
    LOG.info("Input size for job " + jobId + " = " + inputLength
        + ". Number of splits = " + splits.length);
  }

  private void createReduceTasks() {
    for (int i = 0; i < numReduceTasks; i++) {
      TaskImpl task = new ReduceTaskImpl(jobId, i,
          eventHandler,
          remoteJobConfFile,
          conf, numMapTasks,
          taskAttemptListener, jobToken,
          jobCredentials, clock,
          applicationAttemptId.getAttemptId(),
          metrics, appContext);
      addTask(task);
    }
    LOG.info("Number of reduces for job " + jobId + " = " + numReduceTasks);
  }

