  // Cache management state
  private boolean dropCacheBehindWrites;
  private long lastCacheManagementOffset = 0;
  private boolean syncBehindWrites;
  private boolean syncBehindWritesInBackground;

  /** The client name.  It is empty if a datanode is the client */
  private final String clientname;
  private final boolean isClient; 
  private final boolean isDatanode;

  /** the block to receive */
  private final ExtendedBlock block; 
  /** the replica to write */
  private final ReplicaInPipelineInterface replicaInfo;
  /** pipeline stage */
  private final BlockConstructionStage stage;
  private final boolean isTransfer;

  private boolean syncOnClose;
  private long restartBudget;
  /** the reference of the volume where the block receiver writes to */
  private ReplicaHandler replicaHandler;

  /**
   * for replaceBlock response
   */
  private final long responseInterval;
  private long lastResponseTime = 0;
  private boolean isReplaceBlock = false;
  private DataOutputStream replyOut = null;

  private boolean pinning;

  /**
   * Parameter object for BlockReceiver construction.
   */
  static final class ReceiverConfig {
    final ExtendedBlock block;
    final StorageType storageType;
    final DataInputStream in;
    final String inAddr;
    final String myAddr;
    final BlockConstructionStage stage;
    final long newGs;
    final long minBytesRcvd;
    final long maxBytesRcvd;
    final String clientname;
    final DatanodeInfo srcDataNode;
    final DataNode datanode;
    final DataChecksum requestedChecksum;
    final CachingStrategy cachingStrategy;
    final boolean allowLazyPersist;
    final boolean pinning;

    private ReceiverConfig(Builder builder) {
      this.block = builder.block;
      this.storageType = builder.storageType;
      this.in = builder.in;
      this.inAddr = builder.inAddr;
      this.myAddr = builder.myAddr;
      this.stage = builder.stage;
      this.newGs = builder.newGs;
      this.minBytesRcvd = builder.minBytesRcvd;
      this.maxBytesRcvd = builder.maxBytesRcvd;
      this.clientname = builder.clientname;
      this.srcDataNode = builder.srcDataNode;
      this.datanode = builder.datanode;
      this.requestedChecksum = builder.requestedChecksum;
      this.cachingStrategy = builder.cachingStrategy;
      this.allowLazyPersist = builder.allowLazyPersist;
      this.pinning = builder.pinning;
    }

    /** Builder for {@link ReceiverConfig}. */
    static final class Builder {
      private ExtendedBlock block;
      private StorageType storageType;
      private DataInputStream in;
      private String inAddr;
      private String myAddr;
      private BlockConstructionStage stage;
      private long newGs;
      private long minBytesRcvd;
      private long maxBytesRcvd;
      private String clientname;
      private DatanodeInfo srcDataNode;
      private DataNode datanode;
      private DataChecksum requestedChecksum;
      private CachingStrategy cachingStrategy;
      private boolean allowLazyPersist;
      private boolean pinning;

      Builder setBlock(ExtendedBlock block) { this.block = block; return this; }
      Builder setStorageType(StorageType storageType) { this.storageType = storageType; return this; }
      Builder setIn(DataInputStream in) { this.in = in; return this; }
      Builder setInAddr(String inAddr) { this.inAddr = inAddr; return this; }
      Builder setMyAddr(String myAddr) { this.myAddr = myAddr; return this; }
      Builder setStage(BlockConstructionStage stage) { this.stage = stage; return this; }
      Builder setNewGs(long newGs) { this.newGs = newGs; return this; }
      Builder setMinBytesRcvd(long minBytesRcvd) { this.minBytesRcvd = minBytesRcvd; return this; }
      Builder setMaxBytesRcvd(long maxBytesRcvd) { this.maxBytesRcvd = maxBytesRcvd; return this; }
      Builder setClientname(String clientname) { this.clientname = clientname; return this; }
      Builder setSrcDataNode(DatanodeInfo srcDataNode) { this.srcDataNode = srcDataNode; return this; }
      Builder setDataNode(DataNode datanode) { this.datanode = datanode; return this; }
      Builder setRequestedChecksum(DataChecksum requestedChecksum) { this.requestedChecksum = requestedChecksum; return this; }
      Builder setCachingStrategy(CachingStrategy cachingStrategy) { this.cachingStrategy = cachingStrategy; return this; }
      Builder setAllowLazyPersist(boolean allowLazyPersist) { this.allowLazyPersist = allowLazyPersist; return this; }
      Builder setPinning(boolean pinning) { this.pinning = pinning; return this; }

      ReceiverConfig build() {
        return new ReceiverConfig(this);
      }
    }
  }

  /**
   * Primary constructor using a parameter object.
   */
  BlockReceiver(final ReceiverConfig cfg) throws IOException {
    try {
      this.block = cfg.block;
      this.in = cfg.in;
      this.inAddr = cfg.inAddr;
      this.myAddr = cfg.myAddr;
      this.srcDataNode = cfg.srcDataNode;
      this.datanode = cfg.datanode;

      this.clientname = cfg.clientname;
      this.isDatanode = cfg.clientname.length() == 0;
      this.isClient = !this.isDatanode;
      this.restartBudget = datanode.getDnConf().restartReplicaExpiry;
      this.datanodeSlowLogThresholdMs = datanode.getDnConf().datanodeSlowIoWarningThresholdMs;
      this.responseInterval = (long) (datanode.getDnConf().socketTimeout * 0.5);
      this.stage = cfg.stage;
      this.isTransfer = cfg.stage == BlockConstructionStage.TRANSFER_RBW
          || cfg.stage == BlockConstructionStage.TRANSFER_FINALIZED;

      this.pinning = cfg.pinning;
      if (LOG.isDebugEnabled()) {
        LOG.debug(getClass().getSimpleName() + ": " + block
            + "\n  isClient  =" + isClient + ", clientname=" + clientname
            + "\n  isDatanode=" + isDatanode + ", srcDataNode=" + srcDataNode
            + "\n  inAddr=" + inAddr + ", myAddr=" + myAddr
            + "\n  cachingStrategy = " + cfg.cachingStrategy
            + "\n  pinning=" + cfg.pinning);
      }

      if (isDatanode) { //replication or move
        replicaHandler = datanode.data.createTemporary(cfg.storageType, block);
      } else {
        switch (cfg.stage) {
        case PIPELINE_SETUP_CREATE:
          replicaHandler = datanode.data.createRbw(cfg.storageType, block, cfg.allowLazyPersist);
          datanode.notifyNamenodeReceivingBlock(
              block, replicaHandler.getReplica().getStorageUuid());
          break;
        case PIPELINE_SETUP_STREAMING_RECOVERY:
          replicaHandler = datanode.data.recoverRbw(
              block, cfg.newGs, cfg.minBytesRcvd, cfg.maxBytesRcvd);
          block.setGenerationStamp(cfg.newGs);
          break;
        case PIPELINE_SETUP_APPEND:
          replicaHandler = datanode.data.append(block, cfg.newGs, cfg.minBytesRcvd);
          block.setGenerationStamp(cfg.newGs);
          datanode.notifyNamenodeReceivingBlock(
              block, replicaHandler.getReplica().getStorageUuid());
          break;
        case PIPELINE_SETUP_APPEND_RECOVERY:
          replicaHandler = datanode.data.recoverAppend(block, cfg.newGs, cfg.minBytesRcvd);
          block.setGenerationStamp(cfg.newGs);
          datanode.notifyNamenodeReceivingBlock(
              block, replicaHandler.getReplica().getStorageUuid());
          break;
        case TRANSFER_RBW:
        case TRANSFER_FINALIZED:
          replicaHandler =
              datanode.data.createTemporary(cfg.storageType, block);
          break;
        default: throw new IOException("Unsupported stage " + cfg.stage + 
              " while receiving block " + block + " from " + inAddr);
        }
      }
      replicaInfo = replicaHandler.getReplica();
      this.dropCacheBehindWrites = (cfg.cachingStrategy.getDropBehind() == null) ?
        datanode.getDnConf().dropCacheBehindWrites :
          cfg.cachingStrategy.getDropBehind();
      this.syncBehindWrites = datanode.getDnConf().syncBehindWrites;
      this.syncBehindWritesInBackground = datanode.getDnConf().
          syncBehindWritesInBackground;

      final boolean isCreate = isDatanode || isTransfer 
          || cfg.stage == BlockConstructionStage.PIPELINE_SETUP_CREATE;
      streams = replicaInfo.createStreams(isCreate, cfg.requestedChecksum);
      assert streams != null : "null streams!";

      this.clientChecksum = cfg.requestedChecksum;
      this.diskChecksum = streams.getChecksum();
      this.needsChecksumTranslation = !clientChecksum.equals(diskChecksum);
      this.bytesPerChecksum = diskChecksum.getBytesPerChecksum();
      this.checksumSize = diskChecksum.getChecksumSize();

      this.out = streams.getDataOut();
      if (out instanceof FileOutputStream) {
        this.outFd = ((FileOutputStream)out).getFD();
      } else {
        LOG.warn("Could not get file descriptor for outputstream of class " +
            out.getClass());
      }
      this.checksumOut = new DataOutputStream(new BufferedOutputStream(
          streams.getChecksumOut(), HdfsConstants.SMALL_BUFFER_SIZE));
      if (isCreate) {
        BlockMetadataHeader.writeHeader(checksumOut, diskChecksum);
      } 
    } catch (ReplicaAlreadyExistsException bae) {
      throw bae;
    } catch (ReplicaNotFoundException bne) {
      throw bne;
    } catch(IOException ioe) {
      IOUtils.closeStream(this);
      cleanupBlock();

      IOException cause = DatanodeUtil.getCauseIfDiskError(ioe);
      DataNode.LOG.warn("IOException in BlockReceiver constructor. Cause is ",
          cause);

      if (cause != null) {
        ioe = cause;
        datanode.checkDiskErrorAsync();
      }

      throw ioe;
    }
  }

  /**
   * Backward‑compatible constructor.
   */
  BlockReceiver(final ExtendedBlock block, final StorageType storageType,
      final DataInputStream in,
      final String inAddr, final String myAddr,
      final BlockConstructionStage stage, 
      final long newGs, final long minBytesRcvd, final long maxBytesRcvd, 
      final String clientname, final DatanodeInfo srcDataNode,
