	//{{{ main() method
	/**
	 * The main method of the jEdit application.
	 * This should never be invoked directly.
	 * @param args The command line arguments
	 */
	public static void main(String[] args)
	{
		checkJavaVersion();

		Config cfg = parseCommandLine(args);

		if (cfg.settingsDirectory != null && cfg.portFile != null)
			cfg.portFile = MiscUtilities.constructPath(cfg.settingsDirectory, cfg.portFile);
		else
			cfg.portFile = null;

		initLog(cfg.logLevel);

		if (connectToRunningInstance(cfg, args))
			return; // connected and exited

		showSplashIfNeeded();

		initSettingsDirectory(cfg);

		initServerIfNeeded(cfg);

		initializeComponents();

		startPluginsIfNeeded();

		loadMacrosAndStartupScripts(cfg);

		runScriptIfSpecified(cfg);

		propertiesChanged();

		Buffer buffer = openFilesAndRestore(cfg, args);
		String splitConfig = cfg.splitConfig;

		createAndShowView(buffer, splitConfig, cfg.gui);
	} //}}}

	/** Holds parsed command line configuration */
	private static class Config
	{
		int logLevel = Log.WARNING;
		String settingsDirectory;
		String portFile = "server";
		boolean restore = true;
		boolean gui = true;
		boolean noPlugins = false;
		boolean noStartupScripts = false;
		String scriptFile = null;
		boolean background = false;
		String userDir = System.getProperty("user.dir");
		String splitConfig = null;
	}

	/** Checks that the running JVM meets the minimum version requirement */
	private static void checkJavaVersion()
	{
		String javaVersion = System.getProperty("java.version");
		if (javaVersion.compareTo("1.3") < 0)
		{
			System.err.println("You are running Java version " + javaVersion + ".");
			System.err.println("jEdit requires Java 1.3 or later.");
			System.exit(1);
		}
	}

	/** Parses command line arguments and populates a Config object */
	private static Config parseCommandLine(String[] args)
	{
		Config cfg = new Config();

		// log level
		if (args.length >= 1)
		{
			String levelStr = args[0];
			if (levelStr.length() == 1 && Character.isDigit(levelStr.charAt(0)))
			{
				cfg.logLevel = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}

		boolean endOpts = false;
		cfg.settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"), ".jedit");

		for (int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if (arg == null)
				continue;
			else if (arg.length() == 0)
				args[i] = null;
			else if (arg.startsWith("-") && !endOpts)
			{
				if (arg.equals("--"))
					endOpts = true;
				else if (arg.equals("-usage"))
				{
					version();
					System.err.println();
					usage();
					System.exit(1);
				}
				else if (arg.equals("-version"))
				{
					version();
					System.exit(1);
				}
				else if (arg.equals("-nosettings"))
					cfg.settingsDirectory = null;
				else if (arg.startsWith("-settings="))
					cfg.settingsDirectory = arg.substring(10);
				else if (arg.startsWith("-noserver"))
					cfg.portFile = null;
				else if (arg.equals("-server"))
					cfg.portFile = "server";
				else if (arg.startsWith("-server="))
					cfg.portFile = arg.substring(8);
				else if (arg.startsWith("-background"))
					cfg.background = true;
				else if (arg.equals("-nogui"))
					cfg.gui = false;
				else if (arg.equals("-norestore"))
					cfg.restore = false;
				else if (arg.equals("-noplugins"))
					cfg.noPlugins = true;
				else if (arg.equals("-nostartupscripts"))
					cfg.noStartupScripts = true;
				else if (arg.startsWith("-run="))
					cfg.scriptFile = arg.substring(5);
				else
				{
					System.err.println("Unknown option: " + arg);
					usage();
					System.exit(1);
				}
				args[i] = null;
			}
		}
		return cfg;
	}

	/** Initializes the Log subsystem */
	private static void initLog(int level)
	{
		Log.init(true, level);
	}

	/** Attempts to connect to an already running jEdit instance */
	private static boolean connectToRunningInstance(Config cfg, String[] args)
	{
		if (cfg.portFile != null && new File(cfg.portFile).exists())
		{
			try
			{
				BufferedReader in = new BufferedReader(new FileReader(cfg.portFile));
				String check = in.readLine();
				if (!check.equals("b"))
					throw new Exception("Wrong port file format");

				int port = Integer.parseInt(in.readLine());
				int key = Integer.parseInt(in.readLine());
				in.close();

				Socket socket = new Socket(InetAddress.getByName("127.0.0.1"), port);
				DataOutputStream out = new DataOutputStream(socket.getOutputStream());
				out.writeInt(key);

				String script = makeServerScript(cfg.restore, args, cfg.scriptFile);
				out.writeUTF(script);
				out.close();

				System.exit(0);
			}
			catch (Exception e)
			{
				Log.log(Log.NOTICE, jEdit.class, "An error occurred while connecting to the jEdit server instance.");
				Log.log(Log.NOTICE, jEdit.class, "This probably means that jEdit crashed and/or exited abnormally the last time it was run.");
				Log.log(Log.NOTICE, jEdit.class, "If you don't know what this means, don't worry.");
				Log.log(Log.NOTICE, jEdit.class, e);
			}
			return true;
		}
		return false;
	}

	/** Shows the splash screen unless a 'nosplash' file exists */
	private static void showSplashIfNeeded()
	{
		if (!new File(settingsDirectory, "nosplash").exists())
			GUIUtilities.showSplashScreen();
	}

	/** Initializes the settings directory and related paths */
	private static void initSettingsDirectory(Config cfg)
	{
		Writer stream;
		if (cfg.settingsDirectory != null)
		{
			File dir = new File(cfg.settingsDirectory);
			if (!dir.exists())
				dir.mkdirs();
			File macrosDir = new File(cfg.settingsDirectory, "macros");
			if (!macrosDir.exists())
				macrosDir.mkdir();

			String logPath = MiscUtilities.constructPath(cfg.settingsDirectory, "activity.log");
			backupSettingsFile(new File(logPath));

			try
			{
				stream = new BufferedWriter(new FileWriter(logPath));
			}
			catch (Exception e)
			{
				e.printStackTrace();
				stream = null;
			}
		}
		else
			stream = null;

		Log.setLogWriter(stream);
		Log.log(Log.NOTICE, jEdit.class, "jEdit version " + getVersion());
		Log.log(Log.MESSAGE, jEdit.class, "Settings directory is " + cfg.settingsDirectory);
	}

	/** Initializes the edit server if required */
	private static void initServerIfNeeded(Config cfg)
	{
		if (cfg.portFile != null)
		{
			server = new EditServer(cfg.portFile);
			if (!server.isOK())
				server = null;
		}
		else
		{
			if (cfg.background)
			{
				cfg.background = false;
				System.err.println("You cannot specify both the -background and -noserver switches");
			}
		}
	}

