		if (OperatingSystem.hasJava14() && System.getProperty("jedit.nojava14") == null)
		{
			try
			{
				ClassLoader loader = jEdit.class.getClassLoader();
				Class clazz;
				if (loader != null)
					clazz = loader.loadClass("org.gjt.sp.jedit.Java14");
