	/** Opens files from command line and restores previous session if requested */
	private static Buffer openFilesAndRestore(Config cfg, String[] args)
	{
		Buffer buffer = openFiles(null, cfg.userDir, args);
		if (buffer != null)
			cfg.gui = true;

		if (cfg.restore && settingsDirectory != null && jEdit.getBooleanProperty("restore")
			&& (bufferCount == 0 || jEdit.getBooleanProperty("restore.cli")))
		{
			cfg.splitConfig = restoreOpenFiles();
		}

		if (bufferCount == 0 && cfg.gui)
			newFile(null);

		return buffer;
	}

	/** Creates the initial view and finalizes startup */
	private static void createAndShowView(Buffer buffer, String splitConfig, boolean gui)
	{
		final Buffer _buffer = buffer;
		final String _splitConfig = splitConfig;
		final boolean _gui = gui;

		GUIUtilities.advanceSplashProgress();

		SwingUtilities.invokeLater(new Runnable()
		{
			public void run()
			{
				EditBus.send(new EditorStarted(null));

				if (_gui)
				{
					View view;
					if (_buffer != null)
						view = newView(null, _buffer);
					else
						view = newView(null, _splitConfig);
				}

				// Start I/O threads
				VFSManager.start();

				// Start edit server
				if (server != null)
					server.start();

				GUIUtilities.hideSplashScreen();

				Log.log(Log.MESSAGE, jEdit.class, "Startup complete");

				//{{{ Report any plugin errors
				if (pluginErrors != null)
				{
					String caption = jEdit.getProperty(
						"plugin-error.caption" + (pluginErrors.size() == 1 ? "-1" : ""), new Integer[] {
						new Integer(pluginErrors.size()) });

					new ErrorListDialog(
						jEdit.getFirstView(),
						jEdit.getProperty("plugin-error.title"),
						caption, pluginErrors, true);
					pluginErrors.removeAllElements();
				} //}}}

				// Ensure AWT is initialized
				Toolkit.getDefaultToolkit();
			}
		});
	} //}}}

