    public ChartPanel(JFreeChart chart, int width, int height,
           int minimumDrawWidth, int minimumDrawHeight, int maximumDrawWidth,
           int maximumDrawHeight, boolean useBuffer, boolean properties,
           boolean copy, boolean save, boolean print, boolean zoom,
           boolean tooltips) {

        setChart(chart);
        this.chartMouseListeners = new EventListenerList();
        this.info = new ChartRenderingInfo();
        setPreferredSize(new Dimension(width, height));
        this.useBuffer = useBuffer;
        this.refreshBuffer = false;
        this.minimumDrawWidth = minimumDrawWidth;
        this.minimumDrawHeight = minimumDrawHeight;
        this.maximumDrawWidth = maximumDrawWidth;
        this.maximumDrawHeight = maximumDrawHeight;
        this.zoomTriggerDistance = DEFAULT_ZOOM_TRIGGER_DISTANCE;

        // set up popup menu...
        this.popup = null;
        if (properties || copy || save || print || zoom) {
            this.popup = createPopupMenu(properties, copy, save, print, zoom);
        }

        enableEvents(AWTEvent.MOUSE_EVENT_MASK);
        enableEvents(AWTEvent.MOUSE_MOTION_EVENT_MASK);
        setDisplayToolTips(tooltips);
        addMouseListener(this);
        addMouseMotionListener(this);

        this.defaultDirectoryForSaveAs = null;
        this.enforceFileExtensions = true;

        // initialize ChartPanel-specific tool tip delays with
        // values the from ToolTipManager.sharedInstance()
        ToolTipManager ttm = ToolTipManager.sharedInstance();
        this.ownToolTipInitialDelay = ttm.getInitialDelay();
        this.ownToolTipDismissDelay = ttm.getDismissDelay();
        this.ownToolTipReshowDelay = ttm.getReshowDelay();

        this.zoomAroundAnchor = false;
        this.zoomOutlinePaint = Color.blue;
        this.zoomFillPaint = new Color(0, 0, 255, 63);

        this.panMask = InputEvent.CTRL_MASK;
        // for MacOSX we can't use the CTRL key for mouse drags, see:
        // http://developer.apple.com/qa/qa2004/qa1362.html
        String osName = System.getProperty("os.name").toLowerCase();
        if (osName.startsWith("mac os x")) {
            this.panMask = InputEvent.ALT_MASK;
        }

        this.overlays = new java.util.ArrayList();
    }

    // -------------------------------------------------------------------------
    // Core painting logic – refactored to reduce cognitive complexity
    // -------------------------------------------------------------------------

    /**
     * Paints the component by drawing the chart to fill the entire component,
     * but allowing for the insets (which will be non-zero if a border has been
     * set for this component).  To increase performance (at the expense of
     * memory), an off-screen buffer image can be used.
     *
     * @param g  the graphics device for drawing on.
     */
    @Override
    public void paintComponent(Graphics g) {
        super.paintComponent(g);
        if (this.chart == null) {
            return;
        }
        Graphics2D g2 = (Graphics2D) g.create();

        Rectangle2D available = calculateAvailableArea();
        boolean scalingNeeded = computeScaleFactors(available);
        Rectangle2D chartArea = new Rectangle2D.Double(0.0, 0.0,
                scalingNeeded ? this.minimumDrawWidth : available.getWidth(),
                scalingNeeded ? this.minimumDrawHeight : available.getHeight());

        if (this.useBuffer) {
            ensureChartBuffer(g2, available);
            if (this.refreshBuffer) {
                drawChartToBuffer(chartArea);
                this.refreshBuffer = false;
            }
            g2.drawImage(this.chartBuffer,
                    (int) available.getX(),
                    (int) available.getY(),
                    this);
        } else {
            drawChartDirectly(g2, chartArea, available);
        }

        drawOverlays(g2);
        drawZoomRectangle(g2, false);
        g2.dispose();

        this.anchor = null;
        this.verticalTraceLine = null;
        this.horizontalTraceLine = null;
    }

    /**
     * Calculates the drawing area available for the chart, taking insets into
     * account.
     *
     * @return the available rectangle.
     */
    private Rectangle2D calculateAvailableArea() {
        Dimension size = getSize();
        Insets insets = getInsets();
        return new Rectangle2D.Double(insets.left, insets.top,
                size.getWidth() - insets.left - insets.right,
                size.getHeight() - insets.top - insets.bottom);
    }

    /**
     * Computes the scaling factors required to meet the minimum/maximum draw
     * size constraints.
     *
     * @param available the available drawing area.
     * @return true if scaling is required, false otherwise.
     */
    private boolean computeScaleFactors(Rectangle2D available) {
        double drawWidth = available.getWidth();
        double drawHeight = available.getHeight();
        this.scaleX = 1.0;
        this.scaleY = 1.0;
        boolean scale = false;

        if (drawWidth < this.minimumDrawWidth) {
            this.scaleX = drawWidth / this.minimumDrawWidth;
            drawWidth = this.minimumDrawWidth;
            scale = true;
        } else if (drawWidth > this.maximumDrawWidth) {
            this.scaleX = drawWidth / this.maximumDrawWidth;
            drawWidth = this.maximumDrawWidth;
            scale = true;
        }

        if (drawHeight < this.minimumDrawHeight) {
            this.scaleY = drawHeight / this.minimumDrawHeight;
            drawHeight = this.minimumDrawHeight;
            scale = true;
        } else if (drawHeight > this.maximumDrawHeight) {
            this.scaleY = drawHeight / this.maximumDrawHeight;
            drawHeight = this.maximumDrawHeight;
            scale = true;
        }
        return scale;
    }

    /**
     * Ensures that the off‑screen buffer exists and matches the required size.
     *
     * @param g2 the graphics context.
     * @param available the area that the chart will occupy.
     */
    private void ensureChartBuffer(Graphics2D g2, Rectangle2D available) {
        int w = (int) available.getWidth();
        int h = (int) available.getHeight();
        if (this.chartBuffer == null || this.chartBufferWidth != w
                || this.chartBufferHeight != h) {
            this.chartBufferWidth = w;
            this.chartBufferHeight = h;
            GraphicsConfiguration gc = g2.getDeviceConfiguration();
            this.chartBuffer = gc.createCompatibleImage(w, h,
                    Transparency.TRANSLUCENT);
            this.refreshBuffer = true;
        }
    }

    /**
     * Draws the chart onto the off‑screen buffer.
     *
     * @param chartArea the area (in chart coordinates) to draw.
     */
    private void drawChartToBuffer(Rectangle2D chartArea) {
        Graphics2D bufferG2 = (Graphics2D) this.chartBuffer.getGraphics();
        Composite savedComposite = bufferG2.getComposite();
        bufferG2.setComposite(AlphaComposite.getInstance(
                AlphaComposite.CLEAR, 0.0f));
        bufferG2.fillRect(0, 0, this.chartBufferWidth, this.chartBufferHeight);
        bufferG2.setComposite(savedComposite);

        if (this.scaleX != 1.0 || this.scaleY != 1.0) {
            AffineTransform saved = bufferG2.getTransform();
            bufferG2.transform(AffineTransform.getScaleInstance(
                    this.scaleX, this.scaleY));
            this.chart.draw(bufferG2, chartArea, this.anchor, this.info);
            bufferG2.setTransform(saved);
        } else {
            this.chart.draw(bufferG2,
                    new Rectangle2D.Double(0, 0,
                            this.chartBufferWidth, this.chartBufferHeight),
                    this.anchor, this.info);
        }
    }

    /**
     * Draws the chart directly onto the supplied graphics context.
     *
     * @param g2 the graphics context.
     * @param chartArea the area (in chart coordinates) to draw.
     * @param available the area (including insets) where the chart will appear.
     */
    private void drawChartDirectly(Graphics2D g2, Rectangle2D chartArea,
            Rectangle2D available) {
        AffineTransform saved = g2.getTransform();
        g2.translate(available.getX(), available.getY());
        if (this.scaleX != 1.0 || this.scaleY != 1.0) {
            g2.transform(AffineTransform.getScaleInstance(
                    this.scaleX, this.scaleY));
        }
        this.chart.draw(g2, chartArea, this.anchor, this.info);
        g2.setTransform(saved);
    }

    /**
     * Paints all registered overlays.
     *
     * @param g2 the graphics context.
     */
    private void drawOverlays(Graphics2D g2) {
        Iterator iterator = this.overlays.iterator();
        while (iterator.hasNext()) {
            Overlay overlay = (Overlay) iterator.next();
            overlay.paintOverlay(g2, this);
        }
    }

